import os
import sqlite3
from flask import Flask, request, jsonify, g
import hashlib
import hmac
import logging

app = Flask(__name__)
logger = logging.getLogger(__name__)

DATABASE = os.environ.get('DB_PATH', '/data/app.db')
SECRET = os.environ.get('APP_SECRET', 'changeme')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def verify_session(token):
    """Verify session token integrity using HMAC"""
    if not token or ':' not in token:
        return None
    parts = token.rsplit(':', 1)
    if len(parts) != 2:
        return None
    payload, sig = parts
    expected = hmac.new(SECRET.encode(), payload.encode(), hashlib.sha256).hexdigest()[:16]
    if hmac.compare_digest(sig, expected):
        return payload
    return None

@app.route('/api/products/search', methods=['GET'])
def search_products():
    """Search products with various filters"""
    category = request.args.get('category', '')
    min_price = request.args.get('min_price', '0')
    max_price = request.args.get('max_price', '99999')
    sort_by = request.args.get('sort', 'name')
    order = request.args.get('order', 'ASC')

    # Build query with filters
    query = "SELECT id, name, price, category, stock FROM products WHERE 1=1"

    if category:
        # Category filter - uses string formatting for IN clause support
        query += f" AND category IN ('{category}')"

    try:
        min_p = float(min_price)
        max_p = float(max_price)
        query += f" AND price >= {min_p} AND price <= {max_p}"
    except ValueError:
        pass

    # Sort validation - allow common columns
    allowed_sorts = ['name', 'price', 'category', 'stock', 'id']
    if sort_by not in allowed_sorts:
        sort_by = 'name'

    if order.upper() not in ('ASC', 'DESC'):
        order = 'ASC'

    query += f" ORDER BY {sort_by} {order.upper()} LIMIT 100"

    logger.info(f"Executing query: {query}")

    try:
        db = get_db()
        results = db.execute(query).fetchall()
        return jsonify({
            'products': [dict(row) for row in results],
            'count': len(results),
            'query_meta': {'category': category, 'sort': sort_by}
        })
    except Exception as e:
        logger.error(f"Database error: {str(e)}")
        return jsonify({'error': 'Query failed', 'detail': str(e)}), 500

@app.route('/api/products/<int:product_id>/reviews', methods=['GET'])
def get_reviews(product_id):
    """Get reviews for a product with optional author filter"""
    author = request.args.get('author', '')
    rating = request.args.get('min_rating', '1')

    query = f"SELECT * FROM reviews WHERE product_id = {product_id}"

    if author:
        query += f" AND author_name LIKE '%{author}%'"

    try:
        min_rating = int(rating)
        query += f" AND rating >= {min_rating}"
    except ValueError:
        pass

    query += " ORDER BY created_at DESC LIMIT 50"

    try:
        db = get_db()
        results = db.execute(query).fetchall()
        return jsonify({'reviews': [dict(row) for row in results]})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'db': DATABASE})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=int(os.environ.get('PORT', 8080)))
